const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Grafton, NSW location
  const grafton = ee.Geometry.Point([152.93, -28.95]);

  // Define date range: January 14-22, 2020
  const startDate = '2020-01-14';
  const endDate = '2020-01-23'; // Exclusive end

  // Load CHIRPS daily rainfall data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(grafton);

  // Check if collection has data
  const collectionSize = chirps.size().getInfo();
  console.log(`CHIRPS images in range: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No rainfall data available for the date range.');
    console.log('C1');
    return;
  }

  // Sum daily precipitation across the period
  const totalPrecip = chirps.reduce(ee.Reducer.sum());

  // Extract value at Grafton location
  const rainfallMM = totalPrecip.sample(grafton, 5000).first().get('precipitation').getInfo();

  console.log(`Raw precipitation value: ${rainfallMM}`);

  // Validate result
  if (rainfallMM === null || rainfallMM === undefined || isNaN(rainfallMM)) {
    console.log('Calculation returned invalid/null value.');
    console.log('C3');
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const rainfallInches = rainfallMM / 25.4;

  console.log(`Total rainfall Jan 14-22, 2020: ${rainfallMM.toFixed(2)} mm (${rainfallInches.toFixed(2)} inches)`);
  console.log(`Threshold: 6 inches`);
  console.log(`Images processed: ${collectionSize}`);

  // Determine answer
  if (rainfallInches >= 6.0) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
